// The frame's files, browsed on the frame: folders and pictures as thumbnails
// or as a list, a page a screen (swipe, or the arrows), a picture on the whole
// screen with a swipe to the next, a slideshow, and New folder. Thumbnails are
// decoded at the size of their tile (a 12-megapixel JPEG is scaled as it
// decodes), one a pass after the page shows, and kept while the app lives; the
// list decodes nothing.
//
// It looks like the desktop it runs on: each element names its role in the
// desktop's theme (look="button"), and the theme gives that role its look
// (docs/jsx-ui.md "Themes"). With no desktop it keeps its own. app.frame.theme
// gives the two colors an SVG needs: the page's and the accent.
//
// Where you are (the folder, the page, the picture open, the view) is the
// private `spot` field, kept on disk: leave the scene and come back, and it
// opens where you were. A folder being named is kept with frameos.remember.

const IMAGES = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'qoi', 'ppm', 'svg', 'webp']
const LIST_MS = 30 * 1000
const SLIDE_SECONDS = 10

let zoom = 1
const px = (n) => `${Math.round(n * zoom)}px`

const thumbs = new Map() // path -> kept image ref
const failedThumbs = new Set()
let thumbOrder = []
let viewer = { path: '', ref: null }
let listed = { dir: null, at: 0, entries: [] }
const sizes = new Map() // path -> bytes, for the listing in `listed`
let lastPageKey = ''
let chrome = true
let slideAt = 0

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const saveSpot = (spot) => frameos.setState('spot', spot)
const extOf = (name) => (name.includes('.') ? name.split('.').pop().toLowerCase() : '')
const isImage = (name) => IMAGES.includes(extOf(name))
const baseName = (path) => path.replace(/\/$/, '').split('/').pop()

// The folder's own entries: folders (ending in "/") first, then pictures,
// then the rest, by name. A runtime before 2026.11.8 lists every file below,
// so its folders are read off the paths.
function entriesOf(dir) {
  if (listed.dir === dir && Date.now() - listed.at < LIST_MS) return listed.entries
  const prefix = dir ? dir + '/' : ''
  const seen = new Set()
  const entries = []
  for (const path of frameos.listAssets(dir, { shallow: true }) || []) {
    if (!path.startsWith(prefix)) continue
    const rest = path.slice(prefix.length)
    const slash = rest.indexOf('/')
    const entry = slash >= 0 && slash < rest.length - 1 ? prefix + rest.slice(0, slash + 1) : path
    if (!seen.has(entry)) {
      seen.add(entry)
      entries.push(entry)
    }
  }
  const rank = (path) => (path.endsWith('/') ? 0 : isImage(path) ? 1 : 2)
  entries.sort((a, b) => rank(a) - rank(b) || baseName(a).toLowerCase().localeCompare(baseName(b).toLowerCase()))
  listed = { dir, at: Date.now(), entries }
  sizes.clear()
  return entries
}

function loadThumb(path, size, limit) {
  const ref = frameos.loadAssetImage(path, { keep: true, width: size, height: size, fit: 'cover' })
  if (!ref) {
    failedThumbs.add(path)
    return
  }
  thumbs.set(path, ref)
  thumbOrder = thumbOrder.filter((p) => p !== path).concat(path)
  while (thumbOrder.length > limit) {
    const old = thumbOrder.shift()
    frameos.releaseImage(thumbs.get(old))
    thumbs.delete(old)
  }
}

// A theme's color for an SVG: the first `bg-[#…]` (or white, black) among a
// role's classes, a box's or a list of boxes'.
function bgOf(role) {
  const text = Array.isArray(role) ? role.join(' ') : typeof role === 'string' ? role : ''
  const m = /(?:^|\s)bg-(\[#[0-9a-fA-F]{3,8}\]|white|black)(?=\s|$)/.exec(text)
  if (!m) return null
  return m[1] === 'white' ? '#ffffff' : m[1] === 'black' ? '#000000' : m[1].slice(1, -1)
}

function uiOf(app, context) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const theme = app.frame.theme && typeof app.frame.theme === 'object' ? app.frame.theme : null
  // The room it draws in: a window's or a panel's in a layout, else the panel's,
  // turned (app.frame's size is the panel's before the frame's rotation).
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  const shortSide = Math.min(width, height) * (app.frame.scale || 1)
  zoom = Math.max(0.75, Math.min(2.25, Math.round((shortSide / 480) * 4) / 4))
  const page = bgOf(theme && theme.page)
  const tile = theme ? [].concat(theme.tile || []).join(' ') : ''
  return {
    paper,
    themed: !!theme,
    width,
    height,
    scale: app.frame.scale || 1,
    embedded: app.frame.embedded === true,
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    tile: ink ? 'bg-white border-2 border-black' : 'bg-[#1a2030]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    accentText: ink ? 'text-black underline' : 'text-[#60a5fa]',
    press: paper ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    field: ink ? 'bg-white text-black border-2 border-black' : 'bg-[#1a2030] text-white focus:bg-[#232a3a] placeholder:text-[#8b93a7]',
    card: ink ? 'bg-white border-2 border-black' : 'bg-[#141925]',
    line: ink ? 'border-b-2 border-black' : 'border-b border-[#1f2635]',
    bar: ink ? 'bg-white text-black border-b-2 border-black' : 'bg-black/60 text-white',
    // A thumbnail's corners are masked in the page's color: none where a
    // theme's page has no plain color, or its tiles are square.
    pageColor: page || (theme ? null : ink ? '#ffffff' : '#0b0e14'),
    corners: theme ? /(?:^|\s)rounded/.test(tile) : true,
    folder: bgOf(theme && theme.accent) || (ink ? '#000000' : '#60a5fa'),
  }
}

const Corners = ({ size, radius, color }) => {
  const s = Math.round(size * zoom)
  const r = Math.round(radius * zoom)
  return (
    <svg className="absolute inset-0" width={s} height={s} viewBox={`0 0 ${s} ${s}`}>
      <path
        fill={color}
        fillRule="evenodd"
        d={`M0 0H${s}V${s}H0Z M${r} 0H${s - r}A${r} ${r} 0 0 1 ${s} ${r}V${s - r}A${r} ${r} 0 0 1 ${s - r} ${s}H${r}A${r} ${r} 0 0 1 0 ${s - r}V${r}A${r} ${r} 0 0 1 ${r} 0Z`}
      />
    </svg>
  )
}

const FolderGlyph = ({ size, color }) => (
  <svg viewBox="0 0 48 40" className={`w-[${px(size)}] h-[${px(Math.round((size * 40) / 48))}]`}>
    <path fill={color} d="M2 6a4 4 0 0 1 4-4h12l5 5h19a4 4 0 0 1 4 4v23a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4Z" />
    <path fill="#ffffff" fillOpacity="0.25" d="M2 13h44v3H2Z" />
  </svg>
)

const NewFolderGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" d="M3 6.5a1.5 1.5 0 0 1 1.5-1.5H9l2 2h8.5A1.5 1.5 0 0 1 21 8.5v9a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 17.5Z" />
    <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" d="M12 10.5v5M9.5 13h5" />
  </svg>
)

const FileGlyph = ({ size }) => (
  <svg viewBox="0 0 40 48" className={`w-[${px(Math.round((size * 40) / 48))}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="3" strokeLinejoin="round" d="M6 3h19l12 12v30H6Z M25 3v12h12" />
  </svg>
)

const PictureGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2" strokeLinejoin="round" d="M3 5h18v14H3Z M3 16l5-5l4 4l3-3l6 6" />
    <circle cx="16" cy="9" r="1.6" fill="currentColor" />
  </svg>
)

const GridGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="currentColor" d="M4 4h7v7H4ZM13 4h7v7h-7ZM4 13h7v7H4ZM13 13h7v7h-7Z" />
  </svg>
)

const ListGlyph = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="currentColor" d="M4 5h3v3H4ZM9 5.5h11v2H9ZM4 10.5h3v3H4ZM9 11h11v2H9ZM4 16h3v3H4ZM9 16.5h11v2H9Z" />
  </svg>
)

const Chevron = ({ size, left }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.8" strokeLinecap="round" strokeLinejoin="round" d={left ? 'M15 5L8 12L15 19' : 'M9 5L16 12L9 19'} />
  </svg>
)

const Close = ({ size }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    <path fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" d="M6 6L18 18M18 6L6 18" />
  </svg>
)

const Play = ({ size, playing }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}]`}>
    {playing ? <path fill="currentColor" d="M6 5h4v14H6ZM14 5h4v14h-4Z" /> : <path fill="currentColor" d="M7 4.5L19 12L7 19.5Z" />}
  </svg>
)

function sizeText(bytes) {
  if (!(bytes >= 0)) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

// A list row's detail: a folder says so, a file its size where asking is
// cheap. On an ESP32 the files may be on the flash, where each size is a
// lookup by name that takes a good part of a second.
function detailOf(ui, path) {
  if (path.endsWith('/')) return 'Folder'
  const kind = extOf(baseName(path)).toUpperCase()
  if (ui.embedded) return kind
  if (!sizes.has(path)) sizes.set(path, frameos.assetSize(path))
  return [kind, sizeText(sizes.get(path))].filter(Boolean).join(' · ')
}

function Tile({ ui, path, size, onOpen }) {
  const name = baseName(path)
  const folder = path.endsWith('/')
  const ref = thumbs.get(path)
  return (
    <div look="option" className={`flex flex-col w-[${px(size)}] gap-[${px(6)}] ${ui.press} rounded-[${px(12)}]`} onClick={onOpen}>
      <div className={`relative w-[${px(size)}] h-[${px(size)}]`}>
        {ref ? (
          <img className={`w-[${px(size)}] h-[${px(size)}] object-cover`} src={ref} />
        ) : (
          <div
            look="tile"
            className={`flex flex-col items-center justify-center gap-[${px(4)}] w-[${px(size)}] h-[${px(size)}] rounded-[${px(12)}] ${ui.tile} ${ui.muted}`}
          >
            {folder ? <FolderGlyph size={Math.round(size * 0.42)} color={ui.folder} /> : isImage(name) ? null : <FileGlyph size={Math.round(size * 0.34)} />}
            {!folder && !isImage(name) ? <span className={`text-[${px(11)}] font-bold uppercase`}>{extOf(name)}</span> : null}
          </div>
        )}
        {ref && ui.corners && ui.pageColor ? <Corners size={size} radius={12} color={ui.pageColor} /> : null}
      </div>
      <span className={`text-[${px(13)}] text-center truncate px-[${px(2)}]`}>{name}</span>
    </div>
  )
}

function Row({ ui, path, height, onOpen }) {
  const name = baseName(path)
  const folder = path.endsWith('/')
  return (
    <div
      look="option"
      className={`flex items-center gap-[${px(12)}] h-[${px(height)}] px-[${px(10)}] shrink-0 ${ui.line} ${ui.press}`}
      onClick={onOpen}
    >
      <div className={`flex items-center justify-center w-[${px(30)}] shrink-0`}>
        {folder ? <FolderGlyph size={28} color={ui.folder} /> : isImage(name) ? <PictureGlyph size={24} /> : <FileGlyph size={24} />}
      </div>
      <span className={`flex-1 min-w-0 text-[${px(15)}] truncate`}>{name}</span>
      <span look="muted" className={`shrink-0 text-[${px(13)}] ${ui.muted}`}>
        {detailOf(ui, path)}
      </span>
    </div>
  )
}

function Viewer({ ui, spot, pictures, save }) {
  const at = Math.max(0, pictures.indexOf(spot.open))
  const close = () => {
    spot.open = ''
    spot.playing = false
    // Back to the page the picture is on.
    save(spot)
  }
  const step = (by) => {
    if (pictures.length === 0) return
    spot.open = pictures[(at + by + pictures.length) % pictures.length]
    slideAt = Date.now()
    save(spot)
  }
  const ref = viewer.path === spot.open ? viewer.ref : null
  const name = baseName(spot.open)
  const button = `flex items-center justify-center w-[${px(44)}] h-[${px(44)}] rounded-full ${ui.paper ? ui.soft : 'bg-black/50 text-white'} ${ui.press}`
  return (
    <div
      className={`relative flex items-center justify-center w-full h-full ${ui.paper ? 'bg-white' : 'bg-black'}`}
      onClick={() => {
        chrome = !chrome
      }}
      onSwipe={(e) => {
        if (e.direction === 'left') step(1)
        else if (e.direction === 'right') step(-1)
        else if (e.direction === 'down') close()
      }}
    >
      {ref ? (
        <img className="w-full h-full object-contain" src={ref} />
      ) : (
        <span className={`text-[${px(16)}] ${ui.paper ? 'text-black' : 'text-[#8b93a7]'}`}>
          {failedThumbs.has('view:' + spot.open) ? 'This picture cannot be shown.' : 'Opening…'}
        </span>
      )}
      {chrome || ui.paper ? (
        <div look="page" className={`absolute top-0 left-0 right-0 flex items-center gap-[${px(10)}] h-[${px(56)}] px-[${px(12)}] ${ui.bar}`}>
          <div look="button" className={button} onClick={close}>
            <Close size={20} />
          </div>
          <div className={`flex flex-col flex-1 min-w-0`}>
            <span className={`text-[${px(15)}] font-bold truncate`}>{name}</span>
            <span look="muted" className={`text-[${px(12)}] ${ui.paper ? '' : 'text-white/70'} truncate`}>
              {[`${at + 1} of ${pictures.length}`, sizeText(frameos.assetSize(spot.open))].filter(Boolean).join(' · ')}
            </span>
          </div>
          {pictures.length > 1 ? (
            <div
              look="button"
              className={button}
              onClick={() => {
                spot.playing = !spot.playing
                slideAt = Date.now()
                save(spot)
              }}
            >
              <Play size={18} playing={spot.playing} />
            </div>
          ) : null}
        </div>
      ) : null}
      {(chrome || ui.paper) && pictures.length > 1 ? (
        <div look="button" className={`absolute left-[${px(12)}] top-[${px(Math.round(ui.height / zoom / 2) - 22)}] ${button}`} onClick={() => step(-1)}>
          <Chevron size={22} left />
        </div>
      ) : null}
      {(chrome || ui.paper) && pictures.length > 1 ? (
        <div look="button" className={`absolute right-[${px(12)}] top-[${px(Math.round(ui.height / zoom / 2) - 22)}] ${button}`} onClick={() => step(1)}>
          <Chevron size={22} />
        </div>
      ) : null}
    </div>
  )
}

// What is wrong with a new folder's name, in words, or null.
function nameProblem(name, dir, entries) {
  if (!name) return 'Type a name for the folder.'
  if (/[\/\\]/.test(name)) return 'A name cannot have a slash in it.'
  if (name.startsWith('.')) return 'A name cannot start with a dot.'
  if (/[\u0000-\u001f\u007f]/.test(name)) return 'A name cannot have that character in it.'
  const lower = ((dir ? dir + '/' : '') + name).toLowerCase()
  if (entries.some((path) => path.replace(/\/$/, '').toLowerCase() === lower)) return `There is already something called "${name}" here.`
  return null
}

// The New folder card: a name typed on the keyboard, then Create.
function Naming({ ui, naming, spot, entries, done }) {
  const keep = (next) => frameos.remember('naming', next)
  const create = () => {
    const name = String(naming.name || '').trim()
    const problem = nameProblem(name, spot.dir, entries)
    if (problem) return keep({ name: naming.name, error: problem })
    const path = (spot.dir ? spot.dir + '/' : '') + name
    if (!frameos.makeAssetFolder(path)) return keep({ name: naming.name, error: 'The folder could not be made here.' })
    keep(null)
    done(path + '/')
  }
  const button = `flex items-center h-[${px(40)}] px-[${px(14)}] rounded-[${px(10)}] text-[${px(15)}] shrink-0`
  return (
    <div look="card" className={`flex flex-col gap-[${px(6)}] mx-[${px(16)}] mb-[${px(8)}] p-[${px(10)}] rounded-[${px(12)}] shrink-0 ${ui.card}`}>
      <div className={`flex items-center gap-[${px(8)}]`}>
        <input
          look="field"
          className={`flex-1 min-w-0 h-[${px(40)}] px-[${px(10)}] rounded-[${px(8)}] text-[${px(16)}] ${ui.field}`}
          value={naming.name || ''}
          placeholder="Folder name"
          onChange={(e) => keep({ name: e.target.value })}
          onKeyDown={(e) => {
            if (e.key === 'Enter') create()
          }}
        />
        <div look="button" className={`${button} ${ui.soft} ${ui.press}`} onClick={() => keep(null)}>
          Cancel
        </div>
        <div look="primary" className={`${button} font-bold ${ui.accent} ${ui.press}`} onClick={create}>
          Create
        </div>
      </div>
      {naming.error ? (
        <span look="muted" className={`text-[${px(13)}] ${ui.muted}`}>
          {naming.error}
        </span>
      ) : null}
    </div>
  )
}

export function get(app, context) {
  const ui = uiOf(app, context)
  const spot = readSpot(app)
  spot.dir = typeof spot.dir === 'string' ? spot.dir : ''
  spot.page = Math.max(1, spot.page || 1)
  spot.view = spot.view === 'list' ? 'list' : 'grid'
  const save = (next) => saveSpot(next)
  let entries = entriesOf(spot.dir)
  // A folder that went away: back to the top.
  const parent = spot.dir.includes('/') ? spot.dir.slice(0, spot.dir.lastIndexOf('/')) : ''
  if (entries.length === 0 && spot.dir && !entriesOf(parent).includes(spot.dir + '/')) {
    spot.dir = ''
    spot.page = 1
    spot.open = ''
    entries = entriesOf('')
  }
  const pictures = entries.filter((path) => !path.endsWith('/') && isImage(path))

  // The picture open, at the screen's size; the one before goes.
  if (spot.open && pictures.includes(spot.open)) {
    if (spot.playing && pictures.length > 1) {
      if (slideAt === 0) slideAt = Date.now()
      if (Date.now() - slideAt >= SLIDE_SECONDS * 1000 - 500) {
        spot.open = pictures[(pictures.indexOf(spot.open) + 1) % pictures.length]
        slideAt = Date.now()
      }
      frameos.setNextSleep(Math.max(1, SLIDE_SECONDS - (Date.now() - slideAt) / 1000))
    }
    if (viewer.path !== spot.open) {
      if (viewer.ref) frameos.releaseImage(viewer.ref)
      const width = Math.round(ui.width * ui.scale)
      const height = Math.round(ui.height * ui.scale)
      const ref = frameos.loadAssetImage(spot.open, { keep: true, width, height, fit: 'contain' })
      viewer = { path: spot.open, ref }
      if (!ref) failedThumbs.add('view:' + spot.open)
    }
    save(spot)
    return <Viewer ui={ui} spot={spot} pictures={pictures} save={save} />
  }
  if (spot.open) spot.open = ''

  // A folder can be made where the runtime has the call (2026.11.10+).
  const canMake = typeof frameos.makeAssetFolder === 'function'
  const kept = canMake ? frameos.recall('naming') : null
  const naming = kept && typeof kept === 'object' ? kept : null

  // The page: square tiles with their names, or rows, as many as fit.
  const pad = 16
  const gap = 14
  const label = 24
  const rowHeight = 48
  const headerHeight = 60
  const footerHeight = 46
  const namingHeight = naming ? (naming.error ? 90 : 68) : 0
  const roomWidth = ui.width / zoom - pad * 2
  const roomHeight = ui.height / zoom - headerHeight - footerHeight - namingHeight
  const list = spot.view === 'list'
  let cols = 2
  let rows = 1
  let size = 0
  if (list) {
    cols = 1
    rows = Math.max(1, Math.floor(roomHeight / rowHeight))
  } else {
    let best = -1
    for (let r = 1; r <= 6; r++) {
      for (let c = 2; c <= 8; c++) {
        const s = Math.floor(Math.min((roomWidth - gap * (c - 1)) / c, (roomHeight - gap * (r - 1)) / r - label))
        const score = s >= 96 && s <= 220 ? r * c * Math.pow(s, 1.2) : -1
        if (score > best) {
          best = score
          cols = c
          rows = r
          size = s
        }
      }
    }
    if (best < 0) size = Math.floor((roomWidth - gap) / 2)
  }
  const perPage = cols * rows
  const pages = Math.max(1, Math.ceil(entries.length / perPage))
  // After a change of view, or a folder made: the page that holds it.
  const showing = typeof spot.show === 'string' ? entries.indexOf(spot.show) : typeof spot.show === 'number' ? spot.show : -1
  if (showing >= 0) spot.page = Math.floor(showing / perPage) + 1
  delete spot.show
  spot.page = Math.min(spot.page, pages)
  const shown = entries.slice((spot.page - 1) * perPage, spot.page * perPage)
  save(spot)

  // Thumbnails: none on the pass that shows a page, then one a pass (all at
  // once on e-paper, which draws once). The list decodes none.
  const decode = Math.round(size * zoom * ui.scale)
  const limit = ui.embedded ? 24 : 48
  const missing = list ? [] : shown.filter((path) => !path.endsWith('/') && isImage(path) && !thumbs.has(path) && !failedThumbs.has(path))
  const pageKey = `${spot.dir}:${spot.page}:${perPage}:${spot.view}`
  if (missing.length > 0) {
    if (ui.paper) missing.forEach((path) => loadThumb(path, decode, limit))
    else if (pageKey === lastPageKey) loadThumb(missing[0], decode, limit)
  }
  lastPageKey = pageKey
  if (!ui.paper && missing.some((path) => !thumbs.has(path) && !failedThumbs.has(path))) frameos.setNextSleep(0.05)

  const go = (change) => {
    Object.assign(spot, change)
    save(spot)
  }
  const open = (path) => {
    if (path.endsWith('/')) go({ dir: path.replace(/\/$/, ''), page: 1 })
    else if (isImage(path)) {
      chrome = true
      go({ open: path })
    }
  }
  const up = () => {
    const parts = spot.dir.split('/')
    parts.pop()
    go({ dir: parts.join('/'), page: 1 })
  }
  const turn = (by) => {
    const page = spot.page + by
    if (page >= 1 && page <= pages) go({ page })
  }
  // The first entry showing stays in sight across the change.
  const view = (next) => {
    if (next !== spot.view) go({ view: next, show: (spot.page - 1) * perPage })
  }
  const made = (path) => {
    listed = { dir: null, at: 0, entries: [] }
    go({ show: path })
  }

  const wide = ui.width / zoom >= 560
  const crumbs = ['Files', ...(spot.dir ? spot.dir.split('/') : [])]
  const body = []
  if (list) {
    for (const path of shown) body.push(<Row ui={ui} path={path} height={rowHeight} onOpen={() => open(path)} />)
  } else {
    for (let r = 0; r < rows; r++) {
      const row = shown.slice(r * cols, r * cols + cols)
      if (row.length === 0) break
      body.push(
        <div className={`flex gap-[${px(gap)}]`}>
          {row.map((path) => (
            <Tile ui={ui} path={path} size={size} onOpen={() => open(path)} />
          ))}
        </div>
      )
    }
  }
  const gridWidth = cols * size + (cols - 1) * gap
  const square = `flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0`
  const arrow = `flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${ui.soft} ${ui.press}`
  const toggle = (which, glyph) => (
    <div
      look={spot.view === which ? 'selected' : 'button'}
      className={`${square} ${spot.view === which ? ui.accent : `${ui.soft} ${ui.press}`}`}
      onClick={() => view(which)}
    >
      {glyph}
    </div>
  )

  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(10)}] h-[${px(headerHeight)}] px-[${px(pad)}] shrink-0`}>
        {spot.dir ? (
          <div look="button" className={`${square} ${ui.soft} ${ui.press}`} onClick={up}>
            <Chevron size={20} left />
          </div>
        ) : (
          <div look="accent" className={`${square} ${ui.accent}`}>
            <FolderGlyph size={22} color="#ffffff" />
          </div>
        )}
        <div className={`flex items-center gap-[${px(6)}] flex-1 min-w-0`}>
          {crumbs.map((crumb, i) => {
            const last = i === crumbs.length - 1
            const target = crumbs.slice(1, i + 1).join('/')
            return [
              i > 0 ? (
                <span look="muted" className={`text-[${px(18)}] ${ui.muted}`}>
                  /
                </span>
              ) : null,
              <span
                look={last ? undefined : 'muted'}
                className={`text-[${px(last ? 20 : 16)}] ${last ? 'font-bold' : ui.accentText} truncate ${i === 0 && crumbs.length > 3 ? 'shrink-0' : ''}`}
                onClick={last ? undefined : () => go({ dir: target, page: 1 })}
              >
                {crumb}
              </span>,
            ]
          })}
        </div>
        {wide && pictures.length > 0 ? (
          <span look="muted" className={`text-[${px(13)}] ${ui.muted} whitespace-nowrap`}>
            {`${pictures.length} picture${pictures.length === 1 ? '' : 's'}`}
          </span>
        ) : null}
        {toggle('grid', <GridGlyph size={20} />)}
        {toggle('list', <ListGlyph size={20} />)}
        {canMake && !naming ? (
          <div
            look="button"
            className={`flex items-center justify-center gap-[${px(6)}] h-[${px(40)}] ${wide ? `px-[${px(12)}]` : `w-[${px(40)}]`} rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`}
            onClick={() => frameos.remember('naming', { name: '' })}
          >
            <NewFolderGlyph size={20} />
            {wide ? <span className={`text-[${px(14)}]`}>New folder</span> : null}
          </div>
        ) : null}
      </div>
      {naming ? <Naming ui={ui} naming={naming} spot={spot} entries={entries} done={made} /> : null}
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-hidden ${list ? 'items-stretch' : 'items-center'} px-[${px(pad)}]`}
        onSwipe={(e) => {
          if (e.direction === 'left') turn(1)
          else if (e.direction === 'right') turn(-1)
        }}
      >
        {entries.length === 0 ? (
          <div look="muted" className={`flex flex-col items-center justify-center flex-1 self-stretch gap-[${px(8)}] ${ui.muted}`}>
            <FolderGlyph size={56} color={ui.folder} />
            <span className={`text-[${px(16)}]`}>{spot.dir ? 'Nothing in this folder.' : 'The frame has no files yet.'}</span>
          </div>
        ) : list ? (
          <div className="flex flex-col">{body}</div>
        ) : (
          <div className={`flex flex-col gap-[${px(gap)}] w-[${px(gridWidth)}]`}>{body}</div>
        )}
      </div>
      <div className={`flex items-center justify-end gap-[${px(6)}] h-[${px(footerHeight)}] px-[${px(pad)}] shrink-0`}>
        {pages > 1
          ? [
              spot.page > 1 ? (
                <div look="button" className={arrow} onClick={() => turn(-1)}>
                  <Chevron size={18} left />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
              <span look="muted" className={`w-[${px(72)}] text-center text-[${px(13)}] ${ui.muted}`}>{`${spot.page} of ${pages}`}</span>,
              spot.page < pages ? (
                <div look="button" className={arrow} onClick={() => turn(1)}>
                  <Chevron size={18} />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
            ]
          : null}
      </div>
    </div>
  )
}
